const input = $input.first().json;
const body = input.body || input;
const eventType = (body.event || body.payload?.event_type || '').toString();
const payload = body.payload || body;
const scheduledEvent = payload.scheduled_event || payload.event || {};
const invitee = payload.invitee || payload;
const eventName = (scheduledEvent.name || payload.event_name || '').toString();
const eventUri = (scheduledEvent.uri || payload.event_uri || '').toString();
const slugText = `${eventName} ${eventUri}`.toLowerCase();
const isAudit = slugText.includes('revenue leak audit') || slugText.includes('revenue-leak-audit');
if (!isAudit) return [{ json: { ignored: true, reason: 'Not Revenue Leak Audit', eventType, raw: body } }];
const email = (invitee.email || payload.email || '').trim().toLowerCase();
if (!email) throw new Error('Calendly invitee email is required');
const fullName = (invitee.name || payload.name || '').trim();
const firstName = fullName.split(/\s+/)[0] || 'there';
const questions = invitee.questions_and_answers || payload.questions_and_answers || [];
function answer(label) {
  const needle = label.toLowerCase();
  const row = questions.find(q => (q.question || '').toLowerCase().includes(needle));
  return row ? row.answer : '';
}
const start = scheduledEvent.start_time || payload.start_time || invitee.event_start_time;
const end = scheduledEvent.end_time || payload.end_time || invitee.event_end_time;
const startMs = start ? new Date(start).getTime() : NaN;
if (!Number.isFinite(startMs)) throw new Error('Calendly event_start_time is required');
const nowMs = Date.now();
const meetingLink = invitee.event_guest_link || payload.event_guest_link || scheduledEvent.location?.join_url || scheduledEvent.location?.location || payload.location?.join_url || payload.location || '';
const status = eventType.includes('canceled') || eventType.includes('cancelled') ? 'cancelled' : 'scheduled';
const booking = {
  calendly_event_id: scheduledEvent.uuid || scheduledEvent.uri || eventUri,
  calendly_invitee_id: invitee.uuid || invitee.uri || payload.uri || `${email}:${start}`,
  first_name: firstName,
  email,
  clinic_name: answer('clinic') || payload.clinic_name || payload.company_name || '',
  event_start_time: new Date(startMs).toISOString(),
  event_end_time: end ? new Date(end).toISOString() : null,
  event_timezone: scheduledEvent.event_timezone || scheduledEvent.timezone || payload.timezone || invitee.timezone || $env.MEDSPA_BOOKING_TIMEZONE || 'America/Toronto',
  meeting_link: meetingLink,
  status,
  raw_payload: body
};
const offsets = [
  ['confirmation', 0],
  ['three_day', 3 * 24 * 60 * 60 * 1000],
  ['one_day', 24 * 60 * 60 * 1000],
  ['thirty_minute', 30 * 60 * 1000],
  ['fifteen_minute', 15 * 60 * 1000]
];
const reminders = status === 'scheduled' ? offsets.map(([reminder_type, offset]) => {
  const scheduledMs = reminder_type === 'confirmation' ? nowMs : startMs - offset;
  const tooLate = reminder_type !== 'confirmation' && scheduledMs <= nowMs;
  const afterStart = scheduledMs >= startMs;
  return {
    reminder_type,
    scheduled_for: new Date(scheduledMs).toISOString(),
    status: tooLate || afterStart ? 'skipped' : 'scheduled'
  };
}) : [];
return [{ json: { ignored: false, eventType, booking, reminders } }];

const original = $('Normalize + Build Schedule').first().json;
const bookingRows = $input.first().json;
const booking = Array.isArray(bookingRows) ? bookingRows[0] : bookingRows;
if (!booking || !booking.id) throw new Error('Supabase did not return booking id');
return [{ json: { booking, calendly_status: original.booking.status, reminders: original.reminders } }];

const source = $('Prepare Booking Result').first().json;
if (source.calendly_status === 'cancelled') {
  return [{ json: { action: 'cancelled', booking_id: source.booking.id, reminders: [] } }];
}
const reminders = source.reminders.map(r => ({ booking_id: source.booking.id, ...r }));
return [{ json: { action: 'upsert_reminders', booking_id: source.booking.id, reminders } }];
